from mk import *
from lib import fbd
STRICT["on"] = True
import math

def fig():
    g = Fig(560, 260, "מטוטלת: כדור קטן במסה m על חוט באורך L. נקודה 3 היא נקודת שיווי המשקל, ונקודה 1 בגובה h מעליה. חמש נקודות 1 עד 5 על המסלול. הכדור פוגע ברצפה במרחק D")
    O = (220, 20); L = 160
    g.ceiling(150, 290, 20); g.dot(*O)
    for i, ang in enumerate([-40, -20, 0, 20, 40]):
        a = math.radians(ang); x, y = O[0] + L * math.sin(a), O[1] + L * math.cos(a)
        g.line(*O, x, y, stroke="var(--d-dim)" if i else "var(--d-line)", width=1 if i else 1.5, dash="4 3" if i else None)
        g.circle(x, y, 7, fill="var(--d-label)" if i == 0 else "#ffffff", stroke="var(--d-line)"); g.text(x + (12 if ang >= 0 else -12), y + 4, str(i + 1), anchor="start" if ang >= 0 else "end")
    y1 = O[1] + L * math.cos(math.radians(40)); y3 = O[1] + L
    g.line(80, y1, 220, y1, stroke="var(--d-dim)", width=1, dash="3 3"); g.line(80, y3, 220, y3, stroke="var(--d-dim)", width=1, dash="3 3")
    g.dim(90, y1, 90, y3, "h"); g.text(150, 100, "L", anchor="end")
    g.ground(60, 520, 240)
    g.dim(220, 222, 440, 222, "D", offset=0); g.ball(440, 232, 8)
    return g

E(id="bagrut-2015-q4", year=2015, label="2015 שאלה 4", topic="circular", sub="circ-vertical", diff=3, fig=fig,
  stem=r"מטוטלת פשוטה: כדור קטן שמסתו $m$, קשור לתקרת החדר בחוט באורך $L$. מסת החוט זניחה. בניסוי הסיטו תלמידים את הכדור מנקודת שיווי המשקל (נקודה 3) לנקודה 1, שגבוהה ב-$h$ מנקודה 3, ושחררו אותו. אפשר להזניח את התנגדות האוויר. על המסלול מסומנות חמש נקודות (1-5).",
  parts=[
    P("א1", r"באיזו נקודה, או באילו נקודות, גודל התאוצה המשיקית של הכדור הכי גדול?", choice(["1 ו-5", "2 ו-4", "3"], 0), ["principle"], [
        S(r"התאוצה המשיקית", r"בכיוון המשיק פועל רק רכיב הכובד. הוא גדל ככל שהזווית של החוט מהאנך גדלה", r"mg\sin\theta = m\,a_t \;\Rightarrow\; a_t = g\sin\theta", eq=r"\Sigma\vec F = m\vec a"),
        S(r"איפה הזווית הכי גדולה", r"בנקודות הקיצון", r"\theta_{\max}:\ 1,\ 5"),
    ], r"בנקודות 1 ו-5 (הקיצון)", key=r"1 ו-5"),
    P("א2", r"באיזו נקודה, או באילו נקודות, גודל המהירות של הכדור הכי גדול?", choice(["1 ו-5", "2 ו-4", "3"], 2), ["principle"], [
        S(r"שימור אנרגיה", r"החוט ניצב לתנועה ולא עושה עבודה. המהירות הכי גדולה בנקודה הנמוכה, שבה האנרגיה הפוטנציאלית הכי קטנה", r"\tfrac{1}{2}mv^2 = mg(h - y)", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
    ], r"בנקודה 3", key=r"3"),
    P("ב", r"כשהכדור עובר בנקודה הנמוכה ביותר (נקודה 3), האם המתיחות בחוט גדולה מכוח הכובד על הכדור, קטנה ממנו או שווה לו? נמקו.", choice(["גדולה", "קטנה", "שווה"], 0), ["fbd", "principle"], [
        X(r"בנקודה 3 מרכז המעגל מעל הכדור. בוחרים כלפי מעלה כחיובי."),
        D(r"תרשים הכוחות על הכדור בנקודה 3", lambda: fbd([("T", 90, 1.3), ("mg", -90, 0.8)],
            "תרשים כוחות על הכדור בנקודה הנמוכה: מתיחות החוט כלפי מעלה, גדולה מהמשקל, וכוח הכובד כלפי מטה. הכיוון החיובי כלפי מעלה, אל המרכז",
            positive=90, body="ball", note="המרכז מעל")),
        S(r"משוואת כוחות בכיוון המרכז", r"בכיוון החיובי המתיחות, ונגדה הכובד. הכדור נע, ולכן התאוצה הרדיאלית חיובית", r"T - mg = m\,\frac{v^2}{L} > 0", eq=r"a_R = \frac{v^2}{r}"),
    ], r"גדולה", key=r"מתיחות החוט גדולה מכוח הכובד"),
    P("ג", r"מה גודל הכוח השקול על הכדור כשהוא עובר בנקודה הנמוכה ביותר, בעזרת $m$, $L$, $g$, $h$?", choice([r"$\frac{2mgh}{L}$", r"$\frac{mgh}{L}$", r"$mg + \frac{2mgh}{L}$", r"$\frac{2mgL}{h}$"], 0), ["principle", "algebra"], [
        S(r"המהירות בנקודה 3", r"שימור אנרגיה: הכדור יורד את הגובה h", r"mgh = \tfrac{1}{2}m v^2 \;\Rightarrow\; v^2 = 2gh", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
        S(r"הכוח השקול", r"בנקודה הזו אין תאוצה משיקית, ולכן הכוח השקול כולו רדיאלי", r"\Sigma F = m\,\frac{v^2}{L} = \frac{2mgh}{L}", eq=r"a_R = \frac{v^2}{r}"),
    ], r"$\sum F = \frac{2mgh}{L}$", key=r"ΣF = 2mgh/L"),
    P("ד", r"התלמידים ערכו עוד שני ניסויים. בניסוי 1 הם הסיטו את הכדור לנקודה 1 ושחררו אותו. בניסוי 2 הם הסיטו אותו לנקודה 2, שגבוהה ב-$h/2$ מנקודה 3, ושחררו אותו. בשני הניסויים, כשהכדור עבר בנקודה 3, החוט ניתק, והכדור המשיך לנוע עד שפגע ברצפה. $t_1$ ו-$t_2$ הם הזמנים מהניתוק עד הפגיעה ברצפה, בניסוי 1 ובניסוי 2. האם $t_1$ גדול מ-$t_2$, קטן ממנו או שווה לו? נמקו.", choice(["גדול", "קטן", "שווה"], 2), ["principle"], [
        S(r"בנקודה 3", r"בשני הניסויים המהירות אופקית, והכדור באותו גובה מעל הרצפה", r"v_{0y} = 0"),
        S(r"זמן הנפילה", r"זמן הנפילה תלוי רק בגובה, לא במהירות האופקית. נסמן את הגובה מעל הרצפה באות Y", r"Y = \tfrac{1}{2} g t^2 \;\Rightarrow\; t_1 = t_2 = \sqrt{\frac{2Y}{g}}", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
    ], r"שווה", key=r"t1=t2"),
    P("ה", r"$D_1$ ו-$D_2$ הם המרחקים האופקיים שהכדור עובר בזמנים $t_1$ ו-$t_2$. מה היחס בין $D_1$ ל-$D_2$?", num(math.sqrt(2), ""), ["principle", "algebra"], [
        S(r"המהירויות בנקודה 3", r"שימור אנרגיה בכל ניסוי: מהגובה h, ומחצי הגובה", r"v_1 = \sqrt{2gh},\qquad v_2 = \sqrt{2g \cdot \tfrac{h}{2}} = \sqrt{gh}", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
        S(r"היחס", r"באותו זמן נפילה, המרחק האופקי פרופורציוני למהירות האופקית", r"\frac{D_1}{D_2} = \frac{v_1 t}{v_2 t} = \sqrt{\frac{2gh}{gh}} = \sqrt{2}"),
    ], r"$\sqrt{2} \approx 1.41$", key=r"√2"),
  ],
  concepts=["מטוטלת", "תאוצה משיקית", "מתיחות בתחתית", "זריקה אופקית אחרי ניתוק"],
  summary=r"מטוטלת שהחוט שלה ניתק בתחתית: איפה התאוצה המשיקית הכי גדולה, המתיחות והכוח השקול בתחתית, ומרחקי הנחיתה.",
  review="הנחה שלי.\nבמקור סעיף א הוא (1) ו-(2), וכך גם אצלנו. בסעיף ג התלמיד בוחר את הביטוי הנכון מתוך ארבעה.\nמה לבדוק: רק לאשר.")
